package rpg.engine.script;
import java.util.*;
public final class Ast {private Ast(){} public sealed interface Stmt permits Block,Assign,ExprStmt,If,Return,Let{} public record Block(List<Stmt> body)implements Stmt{} public record Assign(String name,Expr value)implements Stmt{} public record Let(String name,Expr value)implements Stmt{} public record ExprStmt(Expr expr)implements Stmt{} public record If(Expr test,Block yes,Block no)implements Stmt{} public record Return(Expr value)implements Stmt{} public sealed interface Expr permits Literal,Variable,Binary,Unary,Call,Member{} public record Literal(Object value)implements Expr{} public record Variable(String name)implements Expr{} public record Binary(String op,Expr a,Expr b)implements Expr{} public record Unary(String op,Expr x)implements Expr{} public record Call(Expr target,List<Expr> args)implements Expr{} public record Member(Expr target,String name)implements Expr{} }
